/**
 * Where Gemini CLI keeps its data, shared by the Gemini usage, session and
 * new session code so they agree on one folder. Owned by the architect:
 * implementers import these and do not edit this file (ask the integrator).
 */
import os from 'node:os';
import path from 'node:path';

import { resolveDir } from '../kit';
import { PluginConfig } from '../types';

/**
 * The Gemini CLI home: the `geminiDir` setting, else
 * $GEMINI_CLI_HOME/.gemini, else ~/.gemini (settings.json, oauth_creds.json,
 * tmp/<project>/chats/).
 */
export function geminiHome(
  config: PluginConfig | null | undefined,
  env: NodeJS.ProcessEnv = process.env,
  home: string = os.homedir()
): string {
  const cliHome = env.GEMINI_CLI_HOME?.trim();
  return resolveDir(
    config?.geminiDir,
    cliHome ? path.join(cliHome, '.gemini') : undefined,
    path.join(home, '.gemini'),
    home
  );
}

/** The `geminiPath` setting as an absolute path, or null when not set. */
export function geminiPathSetting(
  config: PluginConfig | null | undefined,
  home: string = os.homedir()
): string | null {
  const value = config?.geminiPath;
  if (typeof value !== 'string' || !value.trim()) return null;
  return resolveDir(value, undefined, '', home);
}
